#include "g2m/layer/rail_rules.h"
#include "g2m/core/hash.h"
#include "strict_json.h"
#include <algorithm>
#include <cstdio>
#include <cstdlib>
#include <nlohmann/json.hpp>
#include <set>

namespace g2m {
namespace {
using json = nlohmann::json;
// const unsigned char kRailRulesDe[]: the bytes of data/rail_rules/de.json, generated by CMake.
#include "rail_rules_de.inc"
using strict::Reader;

bool read_strings(Reader& rd, const json& o, const std::string& path, const char* key, std::vector<std::string>& out) {
    const auto* v = rd.field(o, path, key); if (!v) return false;
    if (!v->is_array()) return rd.fail(path + "." + key + " must be an array");
    std::set<std::string> seen;
    for (const auto& e : *v) {
        if (!e.is_string() || e.get<std::string>().empty()) return rd.fail(path + "." + key + " holds a non-string or empty entry");
        if (!seen.insert(e.get<std::string>()).second) return rd.fail(path + "." + key + " holds a duplicate");
    }
    out.assign(seen.begin(), seen.end());   // ascending: the order does not matter for the meaning
    return true;
}
}

const RailClassRules* RailRules::find_class(std::string_view railway) const {
    for (const auto& c : classes) if (c.railway == railway) return &c;
    return nullptr;
}
const RailClassRules* RailRules::find_class_id(std::uint8_t id) const {
    for (const auto& c : classes) if (c.id == id) return &c;
    return nullptr;
}

Result<RailRules> load_rail_rules(std::span<const std::byte> bytes) {
    const char* begin = reinterpret_cast<const char*>(bytes.data());
    const json j = json::parse(begin, begin + bytes.size(), nullptr, /*allow_exceptions=*/false);
    if (j.is_discarded()) return make_error(ErrorCode::Malformed, "rail rules: not valid JSON");
    Reader rd;
    const auto fail = [&]() { return make_error(ErrorCode::InvalidArgument, "rail rules: " + rd.err); };
    if (!rd.keys(j, "root", {"format", "country", "source", "classes", "construction", "piece", "structure", "dependency_margin_m"})) return fail();
    std::string format;
    if (!rd.text(j, "root", "format", format)) return fail();
    if (format != "g2m.rail_rules/1") return make_error(ErrorCode::Unsupported, "rail rules: format '" + format + "'");
    RailRules rules;
    {
        const auto* classes = rd.field(j, "root", "classes");
        if (!classes) return fail();
        if (!classes->is_array() || classes->empty() || classes->size() > kRailClassMax + 1u) { rd.fail("classes must be an array of 1..4 entries"); return fail(); }
        std::set<std::string> names; std::set<int> ids;
        for (std::size_t i = 0; i < classes->size(); ++i) {
            const auto& c = (*classes)[i];
            const std::string path = "classes[" + std::to_string(i) + "]";
            RailClassRules out; std::int32_t id = 0;
            if (!rd.keys(c, path, {"railway", "id", "enabled", "gauge_mm", "tracks", "max_grade_permille"}) || !rd.text(c, path, "railway", out.railway) ||
                !rd.integer(c, path, "id", 0, kRailClassMax, id) || !rd.boolean(c, path, "enabled", out.enabled) ||
                !rd.integer(c, path, "gauge_mm", 300, 3000, out.gauge_mm) || !rd.integer(c, path, "tracks", 1, 8, out.tracks) ||
                !rd.integer(c, path, "max_grade_permille", 1, 300, out.max_grade_permille)) return fail();
            if (out.railway.empty() || !names.insert(out.railway).second || !ids.insert(id).second) { rd.fail(path + ": empty or duplicate railway value or id"); return fail(); }
            out.id = static_cast<std::uint8_t>(id);
            rules.classes.push_back(std::move(out));
        }
        std::sort(rules.classes.begin(), rules.classes.end(), [](const auto& a, const auto& b) { return a.id < b.id; });
    }
    {
        const auto* c = rd.field(j, "root", "construction");
        if (!c || !rd.keys(*c, "construction", {"enabled"}) || !rd.boolean(*c, "construction", "enabled", rules.construction_enabled)) return fail();
    }
    {
        const auto* p = rd.field(j, "root", "piece");
        if (!p || !rd.keys(*p, "piece", {"max_length_m", "ground_spacing_m", "smoothing_m", "max_points"}) ||
            !rd.integer(*p, "piece", "max_length_m", 32, 4096, rules.piece_max_length_m) ||
            !rd.integer(*p, "piece", "ground_spacing_m", 1, 200, rules.ground_spacing_m) ||
            !rd.integer(*p, "piece", "smoothing_m", 0, 200, rules.smoothing_m) ||
            !rd.integer(*p, "piece", "max_points", 16, 4096, rules.piece_max_points)) return fail();
    }
    {
        const auto* s = rd.field(j, "root", "structure");
        if (!s || !rd.keys(*s, "structure", {"chain_walk_budget_m", "chain_max_ways", "bridge_not", "tunnel_not"}) ||
            !rd.integer(*s, "structure", "chain_walk_budget_m", 0, 10000, rules.chain_walk_budget_m) ||
            !rd.integer(*s, "structure", "chain_max_ways", 0, 64, rules.chain_max_ways) ||
            !read_strings(rd, *s, "structure", "bridge_not", rules.bridge_not) ||
            !read_strings(rd, *s, "structure", "tunnel_not", rules.tunnel_not)) return fail();
    }
    if (!rd.integer(j, "root", "dependency_margin_m", 1, 64, rules.dependency_margin_m)) return fail();
    rules.content_sha256 = Sha256::of(bytes);
    return rules;
}

std::span<const std::byte> builtin_rail_rules_de_bytes() {
    return {reinterpret_cast<const std::byte*>(kRailRulesDe), sizeof(kRailRulesDe)};
}
const RailRules& builtin_rail_rules_de() {
    static const RailRules rules = [] {
        auto loaded = load_rail_rules(builtin_rail_rules_de_bytes());
        if (!loaded) {
            std::fprintf(stderr, "g2m: embedded data/rail_rules/de.json is invalid: %s\n", loaded.error().message.c_str());
            std::abort();
        }
        return std::move(*loaded);
    }();
    return rules;
}
} // namespace g2m
